);
// When we get a new pattern, the old one is automatically freed!
unique_ptr_delete
(
&
include_pattern_ptr
);
include_pattern_ptr
.
ptr
=
strdup
(
optarg
);
// No leaks, even if an error happens later!
Sharing Safely with SharedPtr
